INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63533093', 63533093, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin JE Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 3330828000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin JE Tahun 2026 Tahap I sebanyak 27.000 vial dengan estimasi harga satuan Rp123.365', 'Spesifikasi Vaksin JE sebagai berikut : 1. Nama Vaksin Japanese Enchepalitis. 2. Komposisi Vaksin Setiap dosis (0.5 ml) mengandung virus JE strain SA-14-14-2. 3. Indikasi Vaksin Mencegah penyakit Japanese Enchepalitis (JE). 4. Kemasan : Dikemas dalam multi dose,  Setiap ampul/vial dilengkapi dengan pelarut,  Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM),  Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan. 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM). 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 985221);
