INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63513640', 63513640, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Balai Besar Perluasan Kesempatan Kerja Bandung Barat', 'Pengadaan Jasa Tenaga Alih Daya Satpam, Petugas Kebersihan dan Pramubakti Satpel Dumai (periode Januari s.d Mei 2026)', 'Jasa Lainnya', 'E-Purchasing', 'Riau, Dumai (Kota)', 330000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Penyedia jasa wajib menyediakan tenaga ali daya kebersihan, satpam dan pramubakti yang bertujuan untuk menjaga kebersihan dan keamanan kantor serta mendukung operasional dan pelayanan publik yang diselenggarakan di SPPKK Dumai. Penyedia jasa juga wajib memastikan seluruh tenaga alih daya menjalankan tugasnya dan menyampaikan laporan pekerjaan kepada user;', 'Jumlah tenaga alih daya yang dibutuhkan yaitu sebanyak 10 orang yang terdiri dari 5 petugas kebersihan, 4 satpam dan 1 pramubakti (teknisi) dengan kualifikasi sebagai berikut :. a. Kualifikasi Umum : - Warga Negara Indonesia - Sehat jasmani dan Rohani yang dibuktikan dengan surat keterangan sehat dari Puskesmas atau klinik kesehatan Pemerintah; - Batas usia pada saat mulai bekerja paling rendah 18 (delapan belas) tahun dan paling tinggi 58 (lima puluh delapan tahun). - b. Kualifikasi Khusus : - Untuk petugas kebersihan berpendidikan paling rendah sekolah dasar/sederajat, sedangkan untuk satpam dan pramubakti berpendidikan paling rendah sekolah menengah pertama/sederajat. - Untuk satuan keamanan memiliki sertifikat keanggotaan satpam Gada Pratama dan pramubakti dapat mengoperasikan komputer; - jujur, ramah, supel, cepat tanggap dan pekerja keras; - berpenampilan bersih dan rapih.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 987540);
